/* Cumulative Radio 365 — serverless live HLS Worker.
 *
 * Serves a deterministic, wall-clock-synced LIVE HLS playlist from the static
 * segment files already published at https://cumulativeweb.com/radio/hls/.
 * No process runs 24/7: every request computes "what segment is on air right
 * now" as a pure function of Date.now(), so all listeners worldwide stay in
 * sync and the media sequence advances forever.
 *
 * Routes:
 *   GET /live.m3u8      — live sliding-window HLS playlist (no ENDLIST)
 *   GET /nowplaying.json — current track, computed with the same
 *                          track-at-time algorithm as the web player
 *                          (radio365-player.js), so the two never disagree.
 *
 * $0: segments are static files on cumulativeweb.com (GitHub Pages), served
 * as absolute URLs — the Worker only generates the tiny playlist text.
 * No R2, no KV, no secrets. Telemetry ships later via the player beacon.
 */


var WINDOW = 60;              // ~10 minutes of audio per playlist (resilience)
var BEHIND = 3;               // segments behind the live edge included
var CORS = { "Access-Control-Allow-Origin": "*" };

/* Cumulative end-time index for binary search: CUM[i] = end of segment i. */
var CUM = new Float64Array(N + 1);
for (var _i = 0; _i < N; _i++) CUM[_i + 1] = CUM[_i] + DURATIONS[_i];

function mod(n, m) { return ((n % m) + m) % m; }
function pad5(n) { var s = String(n); while (s.length < 5) s = "0" + s; return s; }

/* Segment (0..N-1) on air at position `pos` seconds into the loop. */
function findSegment(pos) {
  var lo = 0, hi = N - 1, mid;
  while (lo <= hi) {
    mid = (lo + hi) >> 1;
    if (CUM[mid] <= pos && pos < CUM[mid + 1]) return mid;
    if (CUM[mid] < pos) lo = mid + 1; else hi = mid - 1;
  }
  return N - 1;
}

/* Global segment index on air at nowMs (monotonic across loop wraps). */
function headGlobal(nowMs) {
  var t = (nowMs - EPOCH_MS) / 1000;
  var cycle = Math.floor(t / TOTAL);
  var pos = t - cycle * TOTAL;
  return cycle * N + findSegment(pos);
}

function livePlaylist(nowMs) {
  var head = headGlobal(nowMs);
  var first = head - BEHIND;
  if (first < 0) first = 0;
  var out = [
    "#EXTM3U",
    "#EXT-X-VERSION:3",
    "#EXT-X-TARGETDURATION:" + TARGET,
    "#EXT-X-MEDIA-SEQUENCE:" + first,
    "#EXT-X-INDEPENDENT-SEGMENTS"
  ];
  for (var g = first; g < first + WINDOW; g++) {
    var i = mod(g, N);
    if (i === 0 && g > first) out.push("#EXT-X-DISCONTINUITY");
    out.push("#EXTINF:" + DURATIONS[i].toFixed(6) + ",");
    out.push(SEG_BASE + "/seg" + pad5(i) + ".ts");
  }
  return out.join("\n") + "\n";
}

/* track-at-time — line-for-line port of radio365-player.js.
 * Uses the schedule's own period (21635.912s), NOT the segment total,
 * so now-playing matches the web player exactly. */
function trackAtTime(nowMs) {
  var epochMs = EPOCH_MS, periodMs = PERIOD_S * 1000;
  var posMs = (Math.floor(nowMs) - Math.floor(epochMs)) % periodMs;
  if (posMs < 0) posMs += periodMs;
  var posS = posMs / 1000, i, t;
  for (i = 0; i < TRACKS.length; i++) {
    t = TRACKS[i];
    if (posS >= t.o && posS < t.o + t.d) {
      var diffMs = Math.floor(nowMs) - Math.floor(epochMs);
      var loopIndex = Math.floor(diffMs / periodMs);
      var absLoopStart = Math.floor(epochMs) + loopIndex * periodMs;
      var trackEndAbs = absLoopStart + (t.o + t.d) * 1000;
      return {
        station: "Cumulative Radio 365",
        artist: t.a,
        title: t.t,
        artwork: t.art,
        slot_index: i,
        position_seconds: Math.round((posS - t.o) * 10) / 10,
        track_ends_at: new Date(trackEndAbs).toISOString(),
        stream_url: "https://radio.cumulativeweb.com/live.m3u8",
        status: "ok"
      };
    }
  }
  throw new Error("schedule: no slot contains position " + posS);
}

export default {
  async fetch(request) {
    var url = new URL(request.url);
    if (request.method === "OPTIONS") {
      return new Response(null, { headers: Object.assign({}, CORS, {
        "Access-Control-Allow-Methods": "GET, OPTIONS",
        "Access-Control-Max-Age": "86400"
      })});
    }
    if (url.pathname === "/live.m3u8") {
      return new Response(livePlaylist(Date.now()), { headers: Object.assign({}, CORS, {
        "Content-Type": "application/vnd.apple.mpegurl",
        "Cache-Control": "public, max-age=4",
        "X-Content-Type-Options": "nosniff"
      })});
    }
    if (url.pathname === "/nowplaying.json") {
      try {
        return new Response(JSON.stringify(trackAtTime(Date.now())), { headers: Object.assign({}, CORS, {
          "Content-Type": "application/json",
          "Cache-Control": "public, max-age=10"
        })});
      } catch (e) {
        return new Response(JSON.stringify({ station: "Cumulative Radio 365", status: "error", error: String(e && e.message || e) }), {
          status: 500, headers: Object.assign({}, CORS, { "Content-Type": "application/json" })
        });
      }
    }
    return new Response("Cumulative Radio 365 — live HLS worker. Routes: /live.m3u8, /nowplaying.json", {
      status: 404, headers: CORS
    });
  }
};

